{
  "schema_version": "sections_v1",
  "chapters": [
    {
      "chapter_id": 1,
      "sections": [
        {
          "section_id": 1,
          "title": "The Glass Cannon Glitch",
          "intent": "Introduce Artie's arrival and the discovery of his broken 1 HP / Max Crit state.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Artie confirms his stats are glitched and accepts the tutorial challenge."
        },
        {
          "section_id": 2,
          "title": "Tutorial Gauntlet",
          "intent": "Demonstrate the danger of the 1 HP build against minor mobs.",
          "section_role": "development",
          "target_scene_count": 2,
          "end_condition": "Artie reaches the Boss Room threshold without taking damage."
        },
        {
          "section_id": 3,
          "title": "The Impossible Crit",
          "intent": "The confrontation with the Tutorial Boss and the logic-defying kill.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "The Tutorial Boss dies in one hit and Artie is flagged as a Red Name anomaly."
        }
      ]
    },
    {
      "chapter_id": 2,
      "sections": [
        {
          "section_id": 1,
          "title": "Oakhaven Paranoia",
          "intent": "Artie navigates the first town while hiding his criminal status.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Artie identifies the 'Hit & Run' passive exploit in his skill tree."
        },
        {
          "section_id": 2,
          "title": "The Agility Grind",
          "intent": "Artie gathers intel and basic supplies for his glass-cannon build.",
          "section_role": "development",
          "target_scene_count": 4,
          "end_condition": "Artie locates the dungeon containing the Speedster's Cloak."
        },
        {
          "section_id": 3,
          "title": "Catacomb Entry",
          "intent": "Artie commits to the high-level dungeon dive.",
          "section_role": "transition",
          "target_scene_count": 3,
          "end_condition": "Artie enters the Snail-Shell Catacombs, locking the entrance behind him."
        }
      ]
    },
    {
      "chapter_id": 3,
      "sections": [
        {
          "section_id": 1,
          "title": "The Art of the Kite",
          "intent": "Establish the mechanics of Artie's high-speed combat style.",
          "section_role": "development",
          "target_scene_count": 4,
          "end_condition": "Artie successfully clears the first floor elites using zero-damage kiting."
        },
        {
          "section_id": 2,
          "title": "Deep Catacombs",
          "intent": "Escalate the difficulty and show Artie pushing his agility to the limit.",
          "section_role": "development",
          "target_scene_count": 4,
          "end_condition": "Artie reaches the central vault containing the legendary loot."
        },
        {
          "section_id": 3,
          "title": "The Unseen Heist",
          "intent": "Artie claims the prize and triggers the guild-wide alert.",
          "section_role": "climax",
          "target_scene_count": 4,
          "end_condition": "Artie loots the Key of the Unseen and realizes he is being tracked by players."
        }
      ]
    },
    {
      "chapter_id": 4,
      "sections": [
        {
          "section_id": 1,
          "title": "The Manual Audit",
          "intent": "Introduce the Player Moderator as a direct antagonist.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "The Moderator corners Artie at the dungeon exit."
        },
        {
          "section_id": 2,
          "title": "The High-Speed Chase",
          "intent": "A frantic escape across the map using every movement exploit Artie knows.",
          "section_role": "development",
          "target_scene_count": 4,
          "end_condition": "Artie reaches the physical boundary of the stable game world."
        },
        {
          "section_id": 3,
          "title": "Crossing the Threshold",
          "intent": "Artie makes the desperate choice to enter the Dead-Zone.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "Artie vanishes into the Dead-Zone static, evading the Moderator's grasp."
        }
      ]
    },
    {
      "chapter_id": 5,
      "sections": [
        {
          "section_id": 1,
          "title": "The Iron Wall",
          "intent": "Artie encounters Bulwark and they realize they are both trapped.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Artie and Bulwark agree to a temporary truce to survive the zone."
        },
        {
          "section_id": 2,
          "title": "Turbo-Tanking",
          "intent": "The duo learns to combine their opposite builds (Max HP vs Max AGI).",
          "section_role": "development",
          "target_scene_count": 4,
          "end_condition": "The party successfully clears a glitched mob pack using their new synergy."
        },
        {
          "section_id": 3,
          "title": "The Gate of Glitches",
          "intent": "The pair reaches the final obstacle preventing their escape.",
          "section_role": "transition",
          "target_scene_count": 3,
          "end_condition": "They arrive at the Dead-Zone Gate and trigger the Guardian's spawn."
        }
      ]
    },
    {
      "chapter_id": 6,
      "sections": [
        {
          "section_id": 1,
          "title": "The Physics Wall",
          "intent": "The Guardian proves immune to standard damage, forcing a new strategy.",
          "section_role": "setup",
          "target_scene_count": 4,
          "end_condition": "Artie identifies a way to weaponize the zone's lag and physics bugs."
        },
        {
          "section_id": 2,
          "title": "Overclocking the Server",
          "intent": "Artie pushes his speed to a level that begins to break the local reality.",
          "section_role": "development",
          "target_scene_count": 4,
          "end_condition": "The environment fragments as Artie achieves a 'Critical Velocity' state."
        },
        {
          "section_id": 3,
          "title": "System Crash",
          "intent": "The final blow that shatters the Guardian and the zone itself.",
          "section_role": "climax",
          "target_scene_count": 4,
          "end_condition": "The Guardian is deleted and the resulting explosion shatters the zone boundaries."
        }
      ]
    },
    {
      "chapter_id": 7,
      "sections": [
        {
          "section_id": 1,
          "title": "The Capital Infiltration",
          "intent": "Artie and Bulwark use the server chaos to slip into the capital.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "The duo secures a hidden base within the city's underground."
        },
        {
          "section_id": 2,
          "title": "The Log Purge",
          "intent": "Artie uses his glitched status to access the server's backend logs.",
          "section_role": "development",
          "target_scene_count": 3,
          "end_condition": "Artie successfully wipes his Red Name status and bounty."
        },
        {
          "section_id": 3,
          "title": "The Expansion Key",
          "intent": "Set up the next book by revealing the true purpose of the Key of the Unseen.",
          "section_role": "climax",
          "target_scene_count": 2,
          "end_condition": "Artie unlocks the gate to the new expansion, cementing his role as a System-Breaker."
        }
      ]
    }
  ]
}

